/*
 * List of instructions that cannot throw an exception under any
 * circumstances.  These instructions are the ones that are permissible after
 * an exception is caught but before the corresponding exception range is
 * popped from the stack.
 * The instructions must be in ascending order by numeric operation code.
 */

var _NonThrowingByteCodes = [32]uint8{
	0:  uint8(m_INST_PUSH1),
	1:  uint8(m_INST_PUSH4),
	2:  uint8(m_INST_POP),
	3:  uint8(m_INST_DUP),
	4:  uint8(m_INST_JUMP1),
	5:  uint8(m_INST_JUMP4),
	6:  uint8(m_INST_END_CATCH),
	7:  uint8(m_INST_PUSH_RESULT),
	8:  uint8(m_INST_PUSH_RETURN_CODE),
	9:  uint8(m_INST_STR_EQ),
	10: uint8(m_INST_STR_NEQ),
	11: uint8(m_INST_STR_CMP),
	12: uint8(m_INST_STR_LEN),
	13: uint8(m_INST_LIST),
	14: uint8(m_INST_OVER),
	15: uint8(m_INST_PUSH_RETURN_OPTIONS),
	16: uint8(m_INST_REVERSE),
	17: uint8(m_INST_NOP),
	18: uint8(m_INST_STR_MAP),
	19: uint8(m_INST_STR_FIND),
	20: uint8(m_INST_COROUTINE_NAME),
	21: uint8(m_INST_NS_CURRENT),
	22: uint8(m_INST_INFO_LEVEL_NUM),
	23: uint8(m_INST_RESOLVE_COMMAND),
	24: uint8(m_INST_STR_TRIM),
	25: uint8(m_INST_STR_TRIM_LEFT),
	26: uint8(m_INST_STR_TRIM_RIGHT),
	27: uint8(m_INST_CONCAT_STK),
	28: uint8(m_INST_STR_UPPER),
	29: uint8(m_INST_STR_LOWER),
	30: uint8(m_INST_STR_TITLE),
	31: uint8(m_INST_NUM_TYPE),
}

func _BBAdjustStackDepth(tls *libc.TLS, bbPtr uintptr, consumed int32, produced int32) {
	/* Count of operands produced by the
	 * operation */
	var depth int32
	depth = (*TBasicBlock)(unsafe.Pointer(bbPtr)).FfinalStackDepth
	depth -= consumed
	if depth < (*TBasicBlock)(unsafe.Pointer(bbPtr)).FminStackDepth {
		(*TBasicBlock)(unsafe.Pointer(bbPtr)).FminStackDepth = depth
	}
	depth += produced
	if depth > (*TBasicBlock)(unsafe.Pointer(bbPtr)).FmaxStackDepth {
		(*TBasicBlock)(unsafe.Pointer(bbPtr)).FmaxStackDepth = depth
	}
	(*TBasicBlock)(unsafe.Pointer(bbPtr)).FfinalStackDepth = depth
}

func _BBUpdateStackReqs(tls *libc.TLS, bbPtr uintptr, tblIdx int32, count int32) {
	/* Count of operands for variadic insts */
	var consumed, produced int32
	consumed = _TalInstructionTable[tblIdx].FoperandsConsumed
	produced = _TalInstructionTable[tblIdx].FoperandsProduced
	if consumed == -libc.Int32FromInt32(1)-libc.Int32FromInt32(0x7fffffff) {
		/*
		 * The instruction is variadic; it consumes 'count' operands.
		 */
		consumed = count
	}
	if produced < 0 {
		/*
		 * The instruction leaves some of its variadic operands on the stack,
		 * with net stack effect of '-1-produced'
		 */
		produced = consumed - produced - int32(1)
	}
	_BBAdjustStackDepth(tls, bbPtr, consumed, produced)
}

func _BBEmitOpcode(tls *libc.TLS, assemEnvPtr uintptr, tblIdx int32, count int32) {
	/* Operand count for variadic ops */
	var bbPtr, envPtr, v1, v2 uintptr
	var op, v3 int32
	envPtr = (*TAssemblyEnv)(unsafe.Pointer(assemEnvPtr)).FenvPtr
	/* Compilation environment */
	bbPtr = (*TAssemblyEnv)(unsafe.Pointer(assemEnvPtr)).Fcurr_bb
	/* Current basic block */
	op = _TalInstructionTable[tblIdx].FtclInstCode & int32(0xFF)
	/*
	 * If this is the first instruction in a basic block, record its line
	 * number.
	 */
	if int64((*TBasicBlock)(unsafe.Pointer(bbPtr)).FstartOffset) == int64((*TCompileEnv)(unsafe.Pointer(envPtr)).FcodeNext)-int64((*TCompileEnv)(unsafe.Pointer(envPtr)).FcodeStart) {
		(*TBasicBlock)(unsafe.Pointer(bbPtr)).FstartLine = (*TAssemblyEnv)(unsafe.Pointer(assemEnvPtr)).FcmdLine
	}
	if (*TCompileEnv)(unsafe.Pointer(envPtr)).FcodeNext == (*TCompileEnv)(unsafe.Pointer(envPtr)).FcodeEnd {
		x_TclExpandCodeArray(tls, envPtr)
	}
	v2 = envPtr + 120
	v1 = *(*uintptr)(unsafe.Pointer(v2))
	*(*uintptr)(unsafe.Pointer(v2))++
	*(*uint8)(unsafe.Pointer(v1)) = uint8(uint32(op))
	if (*TCompileEnv)(unsafe.Pointer(envPtr)).FatCmdStart < int32(2) {
		if op == int32(m_INST_START_CMD) {
			v3 = int32(1)
		} else {
			v3 = 0
		}
		(*TCompileEnv)(unsafe.Pointer(envPtr)).FatCmdStart = v3
	}
	_BBUpdateStackReqs(tls, bbPtr, tblIdx, count)
}

